# <=><=><=><=><=> server configuration <=><=><=><=><=>
def _get_server_host():
    s = socket(AF_INET, SOCK_DGRAM)
    try:
        s.connect(("8.8.8.8", 80))
        return s.getsockname()[0]
    finally:
        s.close()


SERVER_HOST = _get_server_host()
